entries[102245] = { ["name"] = "Qian-Le, Courage of Niuzao", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Agility\n+4 Stamina\n+ 2 Haste\n+ 2 Versatility\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 3 Stamina\nEquip: The Endurance of Niuzao absorbs up to 0 damage from one attack that would normally kill you. This effect has a 2 min cooldown. Does not function for non-Tank-specialized characters." }
entries[102246] = { ["name"] = "Xing-Ho, Breath of Yu'lon", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Intellect\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Haste\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 2 Intellect\nEquip: Your damaging spell casts have a chance to empower you with the Essence of Yu'lon, causing you to hurl jade dragonflame at the target, dealing (200% of Spell Power) damage over 4 sec. This damage also affects up to 4 other enemies near the burning target. (Approximately 2.61 procs per minute)" }
entries[102247] = { ["name"] = "Jina-Kang, Kindness of Chi-Ji", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Intellect\n+4 Stamina\n+ 2 Haste\n+ 2 Versatility\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 2 Intellect\nEquip: Your helpful spells have a chance to grant you Spirit of Chi-Ji, increasing all healing done by 5% and causing all overhealing on players to be redistributed to up to 5 nearby injured friends, for 10 sec. (Approximately 0.58 procs per minute)" }
entries[102248] = { ["name"] = "Fen-Yu, Fury of Xuen", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Agility\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Haste\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 2 Agility\nEquip: Your damaging attacks have a chance to trigger a Flurry of Xuen, causing you to deal 7 damage to up to 5 enemies in front of you , every 0.3 sec for 3 sec. (Approximately 1.74 procs per minute)" }
entries[102249] = { ["name"] = "Gong-Lu, Strength of Xuen", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Strength\n+4 Stamina\n+ 2 Critical Strike\n+ 2 Haste\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 2 Strength\nEquip: Your damaging attacks have a chance to trigger a Flurry of Xuen, causing you to deal 7 damage to up to 5 enemies in front of you , every 0.3 sec for 3 sec. (Approximately 1.74 procs per minute)" }
entries[102250] = { ["name"] = "Qian-Ying, Fortitude of Niuzao", ["text"] = "Binds when picked up\nUnique\nBack\n3 Armor\n+1 Strength\n+4 Stamina\n+ 2 Haste\n+ 2 Versatility\n+ 2 Mastery\n\nPrismatic Socket\nSocket Bonus: + 3 Stamina\nEquip: The Endurance of Niuzao absorbs up to 0 damage from one attack that would normally kill you. This effect has a 2 min cooldown. Does not function for non-Tank-specialized characters." }
