entries[102463] = { ["name"] = "Fire-Watcher's Oath", ["text"] = "Binds when picked up\nUse: Transform into an Ordon Fire-Watcher. PvP kills made while transformed have a chance to grant Bloody Coins. (10 Min Cooldown)\n\"Ordon Fire-Watchers carry the ashes of their victims in a special pouch that keeps them smouldering.\"" }
entries[102464] = { ["name"] = "Black Ash", ["text"] = "Binds when picked up\nUse: Coats the enemy in ash, reducing healing taken by 90% for 10 sec. Only usable on the Timeless Isle.\n\"The ashen remains of a sacrifice to Ordos.\"" }
entries[102467] = { ["name"] = "Censer of Eternal Agony", ["text"] = "Binds when picked up\nToy\nUse: Sacrifice 90% of maximum health to become an Emissary of Ordos. While transformed, you are hostile to all players, and killing players grants Bloody Coins. Can only be used on the Timeless Isle, and flags the user for PvP. (1 Hour Cooldown)\n\"Ritualistic sacrifice is a requirement to enter the ranks of the Ordon.\"" }
