entries[102513] = { ["name"] = "Pattern: Drums of Rage", ["text"] = "Binds when picked up\nUnique\nUse: Teaches you how to craft Drums of Rage.\nRequires Pandaria Leatherworking (75)\n\nDrums of Rage\nUse: Increases melee, ranged, and spell haste by 15% for all party and raid members. Lasts 40 sec.\n\nAllies receiving this effect will become Exhausted and be unable to benefit from Bloodlust, Heroism or Time Warp again for 10 min.\n\nDoes not affect allies above level 50. (2 Min Cooldown)\nSell Price:\nRequires Magnificent Hide" }
